//! The MCP read surface, derived from one artifact (`packages/sdk/mcp-catalog.json`,
//! generated by `scripts/gen-mcp-catalog.mjs` from the OpenAPI snapshot and the
//! authored policy). Row A29's whole point: the tool catalog, the mintable
//! `:read` scopes and the api-key path allowance all read THIS, so they cannot
//! disagree the way three hand-maintained lists did.
//!
//! The conformance tests at the bottom assert the three consumers agree:
//! every catalog tool's path is key-allowed, every family capability is
//! mintable, and the key allowance admits nothing the catalog does not name.

use serde::Deserialize;
use std::sync::OnceLock;

const CATALOG_JSON: &str = include_str!("../../../packages/sdk/mcp-catalog.json");

#[derive(Debug, Clone, Deserialize)]
pub struct CatalogTool {
    pub name: String,
    pub path: String,
    pub capability: String,
    #[serde(default)]
    pub summary: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct CatalogFamily {
    pub namespace: String,
    pub capability: String,
    #[serde(default)]
    pub sensitive: bool,
    pub tools: Vec<CatalogTool>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct SensitiveCapability {
    pub capability: String,
    pub namespace: String,
    pub paths: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct Catalog {
    version: u32,
    families: Vec<CatalogFamily>,
    #[serde(default)]
    sensitive_capabilities: Vec<SensitiveCapability>,
}

fn catalog() -> &'static Catalog {
    static CATALOG: OnceLock<Catalog> = OnceLock::new();
    CATALOG.get_or_init(|| {
        let parsed: Catalog =
            serde_json::from_str(CATALOG_JSON).expect("mcp-catalog.json is generated and valid");
        assert_eq!(
            parsed.version, 1,
            "mcp-catalog.json version {} is newer than this reader understands",
            parsed.version
        );
        parsed
    })
}

/// Every family in the derived catalog, sorted by namespace (the admin surface
/// renders this order).
pub fn families() -> &'static [CatalogFamily] {
    &catalog().families
}

/// Sensitive sub-capabilities: reads inside a family that a family grant must
/// NOT imply (ticket correspondence today). Each is grantable on its own.
pub fn sensitive_capabilities() -> &'static [SensitiveCapability] {
    &catalog().sensitive_capabilities
}

/// A capability an MCP admin may hold: a family's `:read`, a declared
/// sensitive sub-capability, or a family's `:write`. The write dial does not
/// expose MCP tools (this release has none); it gates the IF8 proposal
/// pipeline — the agent's authored change is admitted under the dial and
/// still applies only through approval. What it cannot be is a namespace the
/// catalog does not know: that is the dead-grant class row A29 closes.
pub fn is_grantable(capability: &str) -> bool {
    if catalog()
        .sensitive_capabilities
        .iter()
        .any(|s| s.capability == capability)
    {
        return true;
    }
    let Some((ns, action)) = capability.rsplit_once(':') else {
        return false;
    };
    matches!(action, "read" | "write")
        && catalog()
            .families
            .iter()
            .any(|f| f.namespace == ns && f.capability == format!("{ns}:read"))
}

/// Scopes an api key may be minted with, beyond the hand-written connector
/// scopes. Read-only: MCP namespaces have no write tools, so a `:write` scope
/// on a key would map to no permission and reach no path.
pub fn mintable_read_scopes() -> impl Iterator<Item = &'static str> {
    catalog()
        .families
        .iter()
        .map(|f| f.capability.as_str())
        .chain(
            catalog()
                .sensitive_capabilities
                .iter()
                .map(|s| s.capability.as_str()),
        )
}

/// Whether an api key is accepted on this (legacy-mounted, `/api/v1` stripped)
/// path. Exact segment match against a catalog tool path: a `{param}` segment
/// matches any non-empty segment, everything else must be equal. This is the
/// derived half of the middleware allowance; the hand-written connector
/// prefixes remain alongside it.
///
/// Indexed by the family segment (`tickets`, `invoices`, …) so a keyed request
/// costs one map lookup plus the patterns for that family, not a scan of every
/// tool. The catalog's namespace is the first segment after `/api`.
pub fn key_path_allowed(path: &str) -> bool {
    let segments: Vec<&str> = path.trim_matches('/').split('/').collect();
    let Some(family) = segments.get(1) else {
        return false;
    };
    let Some(patterns) = path_index().get(family) else {
        return false;
    };
    patterns
        .iter()
        .any(|pattern| pattern.len() == segments.len() && segments_match(pattern, &segments))
}

/// Tool paths grouped by family segment. Every catalog path is `/api/<family>/…`,
/// so the family is the lookup key and only that family's patterns are tried.
fn path_index() -> &'static std::collections::HashMap<&'static str, Vec<Vec<&'static str>>> {
    use std::sync::OnceLock;
    static INDEX: OnceLock<std::collections::HashMap<&'static str, Vec<Vec<&'static str>>>> =
        OnceLock::new();
    INDEX.get_or_init(|| {
        let mut map: std::collections::HashMap<&'static str, Vec<Vec<&'static str>>> =
            std::collections::HashMap::new();
        for family in &catalog().families {
            for tool in &family.tools {
                let segments: Vec<&'static str> = tool.path.trim_matches('/').split('/').collect();
                if let Some(family) = segments.get(1) {
                    map.entry(*family).or_default().push(segments);
                }
            }
        }
        map
    })
}

fn segments_match(pattern: &[&str], candidate: &[&str]) -> bool {
    pattern.iter().zip(candidate).all(|(p, c)| {
        if p.starts_with('{') && p.ends_with('}') {
            !c.is_empty()
        } else {
            p == c
        }
    })
}

fn path_matches(pattern: &str, candidate: &[&str]) -> bool {
    let segments: Vec<&str> = pattern.trim_matches('/').split('/').collect();
    if segments.len() != candidate.len() {
        return false;
    }
    segments.iter().zip(candidate).all(|(p, c)| {
        if p.starts_with('{') && p.ends_with('}') {
            !c.is_empty()
        } else {
            p == c
        }
    })
}

/// The capability that governs one concrete request path, for diagnostics and
/// the admin surface: the family read capability, or the sensitive
/// sub-capability when the path is one of its declared reads.
pub fn capability_for_path(path: &str) -> Option<&'static str> {
    let candidate: Vec<&str> = path.trim_matches('/').split('/').collect();
    for family in &catalog().families {
        for tool in &family.tools {
            if path_matches(&tool.path, &candidate) {
                return Some(tool.capability.as_str());
            }
        }
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalog_parses_and_has_the_derived_surface() {
        let families = families();
        assert!(
            families.len() >= 80,
            "the derived surface is broad (got {})",
            families.len()
        );
        let tools: usize = families.iter().map(|f| f.tools.len()).sum();
        assert!(
            tools >= 250,
            "every allowed family read is a tool (got {tools})"
        );
    }

    #[test]
    fn never_list_families_are_absent() {
        for ns in [
            "attachments",
            "api-keys",
            "auth",
            "email",
            "events",
            "internal",
            "mcp",
            "me",
            "migration",
            "onboarding",
            "passwords",
            "portal",
            "public",
            "secrets",
        ] {
            assert!(
                !families().iter().any(|f| f.namespace == ns),
                "{ns} must never be in the derived catalog"
            );
        }
    }

    #[test]
    fn excluded_paths_stay_out() {
        for path in [
            "/api/assets/{id}/vault",
            "/api/settings/ai/credentials",
            "/api/sign-offs/{id}/payload",
            "/api/admin/quarantine",
            "/api/calendar-sync/feed/{token}",
            "/api/orgs/{org_id}/service-accounts",
        ] {
            assert!(
                !families()
                    .iter()
                    .flat_map(|f| f.tools.iter())
                    .any(|t| t.path == path),
                "{path} must stay out of the catalog"
            );
        }
    }

    /// Conformance: every catalog tool's path is accepted by the derived key
    /// allowance, and the allowance names nothing outside the catalog. This is
    /// the test that would have caught D3.
    #[test]
    fn catalog_paths_and_key_allowance_agree() {
        for family in families() {
            for tool in &family.tools {
                let concrete = tool
                    .path
                    .split('/')
                    .map(|seg| {
                        if seg.starts_with('{') && seg.ends_with('}') {
                            "018f0a5e-0000-7000-8000-000000000000"
                        } else {
                            seg
                        }
                    })
                    .collect::<Vec<_>>()
                    .join("/");
                assert!(
                    key_path_allowed(&concrete),
                    "{} is a catalog tool but not key-allowed",
                    tool.path
                );
            }
        }
    }

    /// Conformance: every family and sensitive capability is grantable and
    /// mintable, so an admin grant always has a working machine path.
    #[test]
    fn every_catalog_capability_is_grantable_and_mintable() {
        for family in families() {
            assert!(
                is_grantable(&family.capability),
                "{} not grantable",
                family.capability
            );
            assert!(
                mintable_read_scopes().any(|s| s == family.capability),
                "{} not mintable",
                family.capability
            );
        }
        for cap in sensitive_capabilities() {
            assert!(is_grantable(&cap.capability));
            assert!(mintable_read_scopes().any(|s| s == cap.capability));
        }
    }

    #[test]
    fn sensitive_reads_map_to_their_own_capability() {
        let tool = families()
            .iter()
            .flat_map(|f| f.tools.iter())
            .find(|t| t.path == "/api/tickets/{id}/emails")
            .expect("ticket correspondence is a catalog tool");
        assert_eq!(tool.capability, "tickets_correspondence:read");
        assert_eq!(
            capability_for_path("/api/tickets/018f0a5e-0000-7000-8000-000000000000/emails"),
            Some("tickets_correspondence:read")
        );
        assert!(
            families()
                .iter()
                .find(|f| f.namespace == "documents")
                .is_some_and(|f| f.sensitive),
            "documents is marked sensitive (off by default in the admin surface)"
        );
    }

    #[test]
    fn unknown_capabilities_are_refused() {
        for bad in [
            "nonsense:read",
            "nonsense:write",
            "tickets_correspondence:write",
            "tickets",
            "",
        ] {
            assert!(!is_grantable(bad), "{bad} must not be grantable");
        }
        assert!(is_grantable("invoices:read"));
        assert!(is_grantable("tickets_correspondence:read"));
        assert!(
            is_grantable("tickets:write"),
            "the proposal dial stays grantable"
        );
    }
}
